  "prompt": "prompts/physics_committee_terra_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B052",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made individual superconducting artificial atoms coherently observable and controllable, opening a durable new experimental regime for quantum optics and information.",
        "attribution": "Blais provided a decisive theoretical formulation; Wallraff and Schoelkopf led the landmark experimental realization. Girvin's conceptual contributions are also substantial, making a three-person allocation difficult.",
        "maturity": "The platform has been reproduced broadly and has become foundational to superconducting quantum science over two decades.",
        "uncertainties": [
          "The contribution overlaps historically and conceptually with the 2025 recognition of superconducting quantum circuits."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions provided an exceptionally clean, controllable realization of quantum computation and simulation, converting an information-theoretic proposal into precision experiments.",
        "attribution": "Cirac and Zoller supplied seminal architectures and protocols, while Blatt made decisive sustained experimental demonstrations.",
        "maturity": "The results are longstanding, independently replicated, and remain a benchmark quantum platform.",
        "uncertainties": [
          "Quantum-information milestones are distributed across several physical platforms and many contributors."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Peter W. Shor",
        "Andrew M. Steane"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault tolerance established the physical principle that scalable quantum computation can survive imperfect components.",
        "attribution": "Shor, Steane, and Kitaev each made distinct foundational contributions to codes, fault tolerance, and topological protection.",
        "maturity": "The conceptual framework is mature and now guides experimental roadmaps, though full fault-tolerant computation remains incomplete.",
        "uncertainties": [
          "The most consequential practical demonstrations of fault tolerance are still emerging."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric and topological quantum phases reshaped the physical understanding of quantum interference and underpin major developments across condensed matter and quantum control.",
        "attribution": "The Aharonov-Bohm effect and Berry phase are identifiable, complementary landmark insights with clear individual credit.",
        "maturity": "Their physical consequences have been extensively tested and integrated into modern quantum physics.",
        "uncertainties": [
          "The two effects arose in different contexts, so the conceptual unity of a single prize would need careful framing."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision measurement, combining exquisite quantum control with an unprecedented practical standard of time and frequency.",
        "attribution": "Katori originated the magic-wavelength lattice-clock concept, and Ye made defining experimental advances toward record accuracy and broad realization.",
        "maturity": "Independent laboratories have achieved extraordinary precision and the technology has clear, continuing scientific impact.",
        "uncertainties": [
          "The precise division between conceptual invention and the many later technical advances requires careful assessment."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Markus Aspelmeyer",
        "Oskar Painter",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics brought mechanical motion into the quantum-control toolbox, including cooling, measurement, and coherent coupling at the quantum limit.",
        "attribution": "Aspelmeyer, Painter, and Kippenberg were central architects of complementary experimental routes; Cleland also has important claims.",
        "maturity": "The field is well established across multiple device technologies, with quantum signatures convincingly demonstrated.",
        "uncertainties": [
          "Attribution is unusually broad and a three-person selection necessarily leaves out major contributors."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Bart J. van Wees",
        "Henk van Houten",
        "Michael Pepper"
      ],
      "assessment": {
        "nobel_worthiness": "Conductance quantization in quantum point contacts gave a direct and elegant demonstration of transport through discrete quantum modes, inaugurating modern mesoscopic electron physics.",
        "attribution": "van Wees and van Houten led the canonical discovery, while Pepper was a major parallel experimental contributor.",
        "maturity": "The effect is experimentally unambiguous, universally reproduced, and foundational for nanostructure transport.",
        "uncertainties": [
          "Near-simultaneous discoveries and the broader development of ballistic mesoscopic transport complicate a narrow allocation."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and time-reversal-invariant topological insulators revealed a new robust form of electronic quantum matter with far-reaching consequences.",
        "attribution": "Kane and Mele provided the essential theoretical prediction, while Molenkamp led a decisive experimental realization. Hasan also made major experimental contributions.",
        "maturity": "Topological-insulator physics is firmly established experimentally and conceptually.",
        "uncertainties": [
          "This candidate partly overlaps with related topological-insulator and quantum-anomalous-Hall candidates on the longlist."
        ]
      }
    }
  ]
}
